INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('6444cfdb-9528-466f-82a3-4b585d2a32e4', 'otc', 'easy', 'Tension headache request', NULL, NULL, ARRAY['Paracetamol']::text[], '{"age":28,"meds":"none","name":"John","symptoms":"mild headache, no fever","allergies":"none"}'::jsonb, '{"complaint":"I have a mild headache since this morning.","questions":[{"q":"Any associated symptoms?","choices":["No, just the headache","Severe stiff neck","Loss of vision","Vomiting blood"],"correct":0},{"q":"Have you taken any meds today?","choices":["Nothing yet","Paracetamol 1g already","Ibuprofen + alcohol","Codeine"],"correct":0}],"correct_dose":"1-2 tabs every 4-6h, max 4g/day","correct_drug":"Paracetamol 500mg","dose_options":["1-2 tabs every 4-6h, max 4g/day","3 tabs every 2h","1 tab once a day","6 tabs at once"],"drug_options":["Paracetamol 500mg","Ibuprofen 400mg","Aspirin 300mg","Codeine"],"advice_options":["Stay hydrated, rest, see a doctor if no improvement in 3 days","Avoid water","Double the dose if pain persists","Take with alcohol"],"correct_advice":"Stay hydrated, rest, see a doctor if no improvement in 3 days"}'::jsonb, 'Paracetamol is safer first-line OTC analgesic.', 'Ask about alcohol use and other paracetamol-containing products.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.m