INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('6a300398-167a-48aa-be5a-adc84890f57c', 'otc', 'medium', 'Heartburn after dinner', NULL, NULL, ARRAY['Omeprazole']::text[], '{"age":35,"name":"Lina","symptoms":"burning chest after meals 2 weeks","allergies":"none"}'::jsonb, '{"complaint":"I get a burning feeling in my chest after eating.","questions":[{"q":"How long has this been happening?","choices":["2 weeks","Just today","Years","Few hours"],"correct":0},{"q":"Any alarm symptoms?","choices":["No","Black stools","Trouble swallowing","Weight loss"],"correct":0}],"correct_dose":"1 cap daily before breakfast for 14 days","correct_drug":"Omeprazole 20mg","dose_options":["1 cap daily before breakfast for 14 days","3 caps a day with meals","1 cap at bedtime only","As needed only"],"drug_options":["Omeprazole 20mg","Ibuprofen","Amoxicillin","Salbutamol"],"advice_options":["Avoid late meals, elevate head of bed, return if symptoms persist >2 weeks","Eat right before sleeping","Drink coffee with each meal","No lifestyle changes needed"],"correct_advice":"Avoid late meals, elevate head of bed, return if symptoms persist >2 weeks"}'::jsonb, 'Short PPI course for typical reflux is appropriate self-care.', 'Refer red flags: dysphagia, weight loss, GI bleeding.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, men