INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('2fde3482-a6e9-47bb-8e34-ee14ea457e75', 'cosmetic', 'easy', 'Acne moisturizer query', NULL, NULL, ARRAY[]::text[], '{"age":19,"name":"Sara","skin":"oily, acne-prone","current_products":"benzoyl peroxide 5%"}'::jsonb, '{"warnings":["Benzoyl peroxide can bleach fabrics","Increased photosensitivity"],"advice_options":["Apply twice daily, use SPF 30+ every morning","Apply only at night, avoid sunscreen","Layer with oil-based products","Use only after sun exposure"],"correct_advice":"Apply twice daily, use SPF 30+ every morning","correct_product":"Non-comedogenic oil-free moisturizer with niacinamide","product_options":["Non-comedogenic oil-free moisturizer with niacinamide","Heavy occlusive ointment","Oil-based cleansing balm","Coconut oil"]}'::jsonb, 'Pair actives with a barrier-friendly moisturizer and daily SPF.', 'Recommend SPF in the morning — many acne treatments increase photosensitivity.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('cf27381a-a68f-4d84-9694-47a9840957dd', 'cosmetic', 'easy', 'Hair loss after pregnancy', NULL, NULL, ARRAY[]::text[], '{"age":30,"name":"Mona","concern":"Diffuse hair shedding 3 months postpartum"}'::jsonb, '{"warnings":["Refer if persists beyond 12 months"],"advice_options":["Postpartum telogen effluvium usually resolves in 6-12 months; eat balanced diet","Cut hair very short permanently","Take high-dose vitamin A","Avoid all proteins"],"correct_advice":"Postpartum telogen effluvium usually resolves in 6-12 months; eat balanced diet","correct_product":"Gentle volumizing shampoo + biotin supplement, reassurance","product_options":["Gentle volumizing shampoo + biotin supplement, reassurance","Minoxidil 5% immediately","Hair dye treatment","Stop all hair products"]}'::jsonb, 'Education + gentle care is first-line.', 'Reassurance is treatment too — postpartum shedding is normal and self-limiting.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('f8c958b3-442a-4501-a38a-cb89423471d2', 'emergency', 'hard', 'Anaphylaxis after penicillin', NULL, NULL, ARRAY[]::text[], '{"age":30,"name":"ER patient","cause":"amoxicillin 10 min ago","symptoms":"hives, wheeze, BP 80/50"}'::jsonb, '{"emergency":"Anaphylaxis","correct_dose":"0.5 mg IM lateral thigh","correct_drug":"Epinephrine (Adrenaline)","dose_options":["0.5 mg IM lateral thigh","1 mg IV push","10 mg PO","0.01 mg subcutaneous"],"drug_options":["Epinephrine (Adrenaline)","Diphenhydramine","Salbutamol","Paracetamol"],"correct_route":"IM","route_options":["IM","IV","PO","SC"]}'::jsonb, 'IM epinephrine 0.3-0.5 mg in the lateral thigh is the immediate life-saving step.', 'Adrenaline first, antihistamines second — order matters.', '2026-06-10T11:26:39.62631+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
