INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('0ff363d7-95ae-4f30-bbd6-ca49b2e1be74', 'otc', 'easy', 'Mild cold', NULL, NULL, ARRAY[]::text[], '{"age":34,"name":"Tariq","gender":"M","allergies":"none","current_meds":"none"}'::jsonb, '{"complaint":"Blocked nose and sneezing for 2 days.","questions":[{"q":"Any fever or productive cough?","choices":["No","Yes, high fever","Bloody sputum"],"correct":0}],"correct_dose":"1 spray per nostril BD, max 7 days","correct_drug":"Xylometazoline nasal spray","dose_options":["1 spray per nostril BD, max 7 days","4 sprays each nostril QID","1 spray once a week"],"drug_options":["Xylometazoline nasal spray","Salbutamol inhaler","Co-amoxiclav"],"advice_options":["Use max 5-7 days to avoid rebound congestion; saline rinse is a good adjunct.","Use continuously until better","Combine with antibiotic"],"correct_advice":"Use max 5-7 days to avoid rebound congestion; saline rinse is a good adjunct."}'::jsonb, 'Viral cold — symptomatic only, no antibiotic.', 'Decongestant rebound (rhinitis medicamentosa) is the classic counseling point.', '2026-06-13T08:49:53.804255+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_comp