INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('59840994-cf76-47ab-80d5-10a844d74734', 'hospital', 'easy', 'Community-acquired pneumonia', NULL, NULL, ARRAY[]::text[], '{"age":55,"labs":{"WBC":"14","eGFR":78},"name":"Mrs. Saeed","vitals":{"BP":"128/80","HR":90,"SpO2":"95%","Temp":"38.5"},"allergies":"none","diagnosis":"CAP - CURB-65: 1","current_meds":"none"}'::jsonb, '{"drugs":[{"dose":"500mg","drug":"Amoxicillin","route":"oral","frequency":"three times daily"},{"dose":"500mg","drug":"Clarithromycin","route":"oral","frequency":"twice daily"}],"remove":[]}'::jsonb, 'CAP moderate severity — beta-lactam + macrolide for atypical cover.', 'IV-to-oral switch as soon as patient is afebrile and tolerating oral.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('f3d59250-d5c3-47bf-bdb9-1be647a7bb6e', 'otc', 'easy', 'Insect bite reaction', NULL, NULL, ARRAY[]::text[], '{"age":24,"name":"Sara","gender":"F","allergies":"none","current_meds":"none"}'::jsonb, '{"complaint":"Itchy raised bumps on my arm after gardening.","questions":[{"q":"Any breathing issues or facial swelling?","choices":["No, just itchy","Yes, lips swelling","I feel dizzy"],"correct":0}],"correct_dose":"Apply thinly BD for up to 7 days","correct_drug":"Hydrocortisone cream","dose_options":["Apply thinly BD for up to 7 days","Apply thickly TDS for 4 weeks","Single application only"],"drug_options":["Hydrocortisone cream","Mupirocin","Benzoyl Peroxide"],"advice_options":["Apply thin layer twice daily for max 7 days. Avoid face and broken skin.","Use under occlusion overnight","Apply with bandage continuously"],"correct_advice":"Apply thin layer twice daily for max 7 days. Avoid face and broken skin."}'::jsonb, 'Mild topical steroid is adequate for localized reaction; refer if systemic signs.', 'Always rule out anaphylaxis before recommending topical therapy.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('07be4223-3c9b-46a2-b4e6-5e6e2c734fd4', 'otc', 'medium', 'Diarrhea with mild dehydration', NULL, NULL, ARRAY[]::text[], '{"age":40,"name":"Bilal","gender":"M","allergies":"none","current_meds":"none"}'::jsonb, '{"complaint":"Loose stools 5x today, feeling thirsty and tired.","questions":[{"q":"Any blood in stool or fever?","choices":["No","Yes, blood","High fever for 3 days"],"correct":0},{"q":"Recent travel or new foods?","choices":["Ate street food yesterday","No","On holiday abroad"],"correct":0}],"correct_dose":"1 sachet in 200mL water, sip after each loose stool","correct_drug":"ORS","dose_options":["1 sachet in 200mL water, sip after each loose stool","Concentrated double-strength","Once daily only"],"drug_options":["ORS","Loperamide","Ciprofloxacin"],"advice_options":["Prioritize fluid replacement; loperamide only if no fever/blood and travel logistics demand.","Avoid all fluids until diarrhea stops","Drink only milk"],"correct_advice":"Prioritize fluid replacement; loperamide only if no fever/blood and travel logistics demand."}'::jsonb, 'Rehydration first; antibiotics not needed for uncomplicated travelers'' diarrhea.', 'Refer if blood/mucus, persistent fever, severe dehydration, or symptoms >72h.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanatio