INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('2004bf42-9394-4b3c-8fea-fc89f826cb75', 'otc', 'medium', 'Heartburn', NULL, NULL, ARRAY[]::text[], '{"age":38,"name":"Naila","gender":"F","allergies":"none","current_meds":"none"}'::jsonb, '{"complaint":"Burning in chest after meals, worse at night.","questions":[{"q":"Any chest pain on exertion or radiation to arm?","choices":["No, only after meals","Yes, when walking upstairs","Radiates to jaw"],"correct":0},{"q":"Trigger foods?","choices":["Spicy + late dinners","Random","Only with water"],"correct":0}],"correct_dose":"20mg OD before breakfast for 2 weeks","correct_drug":"Omeprazole","dose_options":["20mg OD before breakfast for 2 weeks","20mg every 2 hours","80mg single dose at night"],"drug_options":["Omeprazole","Ranitidine","Ibuprofen"],"advice_options":["Take 30-60 min before breakfast; review in 2 weeks if no improvement, refer to GP.","Take with NSAIDs to prevent ulcers","Combine with antacid every hour"],"correct_advice":"Take 30-60 min before breakfast; review in 2 weeks if no improvement, refer to GP."}'::jsonb, 'Empirical PPI trial for uncomplicated GERD after ruling out cardiac red flags.', 'Alarm symptoms (ALARMS-55): Anemia, Loss of weight, Anorexia, Recent onset, Melena, Swallowing difficulty, age>55 → refer.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation 