INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('d6ef3f63-48dc-4634-926b-01e22acb314d', 'otc', 'hard', 'Chest pain mimic — refer', NULL, NULL, ARRAY[]::text[], '{"age":58,"name":"Mr. Yasin","gender":"M","allergies":"none","current_meds":"Aspirin 75, Amlodipine 5"}'::jsonb, '{"complaint":"Burning chest, came on while walking up stairs.","questions":[{"q":"Does it radiate to arm/jaw? Sweating?","choices":["Yes, left arm + sweaty","Only after meals","No"],"correct":0},{"q":"Action?","choices":["Sell antacid","Refer to ED immediately","Recommend exercise"],"correct":1}],"correct_dose":"Call ambulance, give aspirin 300mg chewed if no contraindication","correct_drug":"Refer to ED — possible ACS","dose_options":["Call ambulance, give aspirin 300mg chewed if no contraindication","Walk to GP next week","Try home remedies"],"drug_options":["Refer to ED — possible ACS","Omeprazole 40mg","Ranitidine 150mg"],"advice_options":["Do not dispense — refer immediately. Document time of onset.","Reassure and send home","Recommend bed rest"],"correct_advice":"Do not dispense — refer immediately. Document time of onset."}'::jsonb, 'Exertional ''burning'' chest pain with CV risk factors is ACS until proven otherwise.', 'Always screen for cardiac red flags in any chest complaint — don''t anchor on GI dx.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, expla