INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('2cbeb46e-e77d-4657-827f-9439be6e7bc6', 'hospital', 'easy', 'Post-op pain - General Ward', NULL, NULL, ARRAY[]::text[], '{"age":48,"labs":{"Cr":78,"eGFR":92},"name":"Mr. Khan","vitals":{"BP":"125/78","HR":82,"Temp":"37.0"},"allergies":"none","diagnosis":"Post-cholecystectomy day 1","current_meds":"none"}'::jsonb, '{"drugs":[{"dose":"1g","drug":"Paracetamol","route":"IV","frequency":"four times daily"},{"dose":"50mg","drug":"Tramadol","route":"IV","frequency":"as needed"}],"remove":[]}'::jsonb, 'Multimodal analgesia is standard post-op; paracetamol scheduled + opioid PRN.', 'Always add laxative when prescribing opioids beyond 48h.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('777be094-2aaf-47d3-8d32-9f14e252dbf9', 'hospital', 'medium', 'CKD patient with UTI', NULL, NULL, ARRAY[]::text[], '{"age":71,"labs":{"K":4.8,"Cr":160,"eGFR":42},"name":"Mr. Bashir","vitals":{"BP":"140/85","HR":78,"Temp":"38.1"},"allergies":"none","diagnosis":"Complicated UTI","current_meds":"Amlodipine 5mg"}'::jsonb, '{"drugs":[{"dose":"200mg","drug":"Cefixime","route":"oral","frequency":"twice daily"}],"remove":[]}'::jsonb, 'Renal-adjusted dose (eGFR 30-60): cefixime 200mg BD. Avoid nitrofurantoin (eGFR<45).', 'Always check renal function before quinolones, aminoglycosides, and many antibiotics.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('e04c01b1-198b-4840-850b-4fb496026050', 'hospital', 'medium', 'Elderly polypharmacy review', NULL, NULL, ARRAY[]::text[], '{"age":82,"labs":{"K":3.2,"eGFR":48},"name":"Mrs. Jamal","vitals":{"BP":"108/65","HR":58},"allergies":"none","diagnosis":"Falls risk + AF + HTN","current_meds":"Diazepam 5mg HS, Amitriptyline 25mg, Furosemide 40mg, Warfarin 3mg"}'::jsonb, '{"drugs":[{"dose":"3mg","drug":"Warfarin","route":"oral","frequency":"once daily"}],"remove":["Diazepam","Amitriptyline"]}'::jsonb, 'STOPP criteria: stop diazepam (fall risk) and amitriptyline (anticholinergic). Hypokalemia from furosemide needs review.', 'Beers/STOPP criteria — review benzodiazepines, anticholinergics, and NSAIDs in elderly.', '2026-06-13T08:50:30.541225+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('f366348b-b2ff-4bcc-a407-5f06242513f6', 'oncology', 'medium', 'CHOP for DLBCL', NULL, NULL, ARRAY[]::text[], '{"age":62,"labs":{"ANC":"3.1","WBC":"5.2"},"name":"Mr. Naseer","height":178,"weight":80,"regimen":"R-CHOP - Cyclophosphamide 750 mg/m2","diagnosis":"DLBCL stage III"}'::jsonb, '{"monitor":["CBC","Cardiac (LVEF)","Renal function","LFTs"],"bsa_dose":1463,"supportive":["Ondansetron","Dexamethasone","G-CSF","IV hydration"]}'::jsonb, 'BSA ≈ 1.95 m2 × 750 = 1463mg cyclophosphamide. Add G-CSF for primary prophylaxis (FN risk >20%).', 'MESNA is required for cyclophosphamide doses >1g/m2 to prevent hemorrhagic cystitis.', '2026-06-13T08:50:58.744219+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
