INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('da4a97c7-9032-4590-9173-276028069c60', 'hospital', 'medium', 'IV-to-oral switch', NULL, NULL, ARRAY[]::text[], '{"age":45,"labs":{"WBC":"9","eGFR":85},"name":"Mr. Hamid","vitals":{"BP":"125/80","HR":76,"Temp":"36.8"},"allergies":"none","diagnosis":"Cellulitis day 4 - improving","current_meds":"IV Co-amoxiclav 1.2g TDS"}'::jsonb, '{"drugs":[{"dose":"625mg","drug":"Co-amoxiclav","route":"oral","frequency":"three times daily"}],"remove":[]}'::jsonb, 'Patient meets switch criteria: afebrile 24h, tolerating PO, clinically improving.', 'IV-to-oral switch saves cost, reduces line infections, and shortens admission.', '2026-06-13T08:50:58.744219+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('00d0ce16-9491-426b-ada8-c168ea94dd9d', 'hospital', 'hard', 'ICU polypharmacy interactions', NULL, NULL, ARRAY[]::text[], '{"age":67,"labs":{"K":5.4,"INR":2.1,"eGFR":35},"name":"Mr. Rauf","vitals":{"BP":"95/55","HR":110,"Temp":"38.9"},"allergies":"Penicillin","diagnosis":"Sepsis post-op","current_meds":"Warfarin, Digoxin, Furosemide"}'::jsonb, '{"drugs":[{"dose":"400mg","drug":"Ciprofloxacin","route":"IV","frequency":"twice daily"}],"remove":["Warfarin","Digoxin"]}'::jsonb, 'Hold warfarin (INR 2.1 + ciprofloxacin = bleeding); hold digoxin (CKD + cipro = toxicity). Avoid beta-lactams (pen allergy).', 'Cipro is a CYP1A2 inhibitor — increases warfarin INR and digoxin levels.', '2026-06-13T08:50:58.744219+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('a3923a0e-bdca-42f7-8e5e-4ec12e63693d', 'oncology', 'easy', 'Tamoxifen maintenance', NULL, NULL, ARRAY[]::text[], '{"age":55,"name":"Mrs. Naz","height":162,"weight":68,"regimen":"Tamoxifen 20mg OD x 5y","diagnosis":"ER+ Breast Ca post-op"}'::jsonb, '{"monitor":["LFTs","Cardiac (LVEF)"],"bsa_dose":20,"supportive":["Folic acid 1mg daily"]}'::jsonb, '20mg fixed daily dose — not BSA-based. Monitor for VTE and endometrial changes.', 'Counsel on hot flashes and the small but real endometrial cancer risk.', '2026-06-13T08:50:58.744219+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('11ca2b5f-1650-4b32-b839-9ae942d859f8', 'oncology', 'medium', 'Weekly methotrexate - RA', NULL, NULL, ARRAY[]::text[], '{"age":52,"name":"Mrs. Ashraf","height":160,"weight":65,"regimen":"MTX 15mg PO weekly","diagnosis":"Rheumatoid Arthritis"}'::jsonb, '{"monitor":["CBC","LFTs","Renal function"],"bsa_dose":15,"supportive":["Folic acid 1mg daily"]}'::jsonb, 'Low-dose weekly MTX with folate cover (NOT folinic — different timing).', 'Most common fatal error in oncology: daily instead of weekly methotrexate dosing.', '2026-06-13T08:50:58.744219+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('649455b1-ab98-4fef-94f9-2a6f8e76262f', 'oncology', 'hard', 'Cisplatin-based HEC protocol', NULL, NULL, ARRAY[]::text[], '{"age":58,"labs":{"K":4.1,"Mg":0.9,"eGFR":78},"name":"Mr. Shahid","height":172,"weight":72,"regimen":"Cisplatin 75 mg/m2 + Etoposide","diagnosis":"NSCLC stage IIIB"}'::jsonb, '{"monitor":["Renal function","Electrolytes","CBC","BSA recheck"],"bsa_dose":140,"supportive":["Ondansetron","Dexamethasone","IV hydration"]}'::jsonb, 'BSA ≈ 1.87 m2 × 75 = 140mg. Pre/post hydration with KCl + MgSO4 mandatory.', 'Cisplatin = high emetogenic — NK1 antagonist (aprepitant) + 5HT3 + dexamethasone triplet is standard.', '2026-06-13T08:50:58.744219+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('d5eba96c-b828-43e8-9cf9-d9760c9a6834', 'oncology', 'hard', 'High-dose MTX with leucovorin rescue', NULL, NULL, ARRAY[]::text[], '{"age":14,"labs":{"eGFR":110,"pH urine":"7.8"},"name":"Master Imran","height":155,"weight":45,"regimen":"MTX 5 g/m2 IV over 24h","diagnosis":"ALL consolidation"}'::jsonb, '{"monitor":["Renal function","LFTs","CBC","Electrolytes"],"bsa_dose":6925,"supportive":["IV hydration","Dexamethasone","Ondansetron"]}'::jsonb, 'BSA ≈ 1.385 m2 × 5000 = 6925mg. Urine alkalinization + leucovorin rescue critical.', 'Folinic acid (leucovorin) rescue — NOT folic acid — for high-dose MTX.', '2026-06-13T08:50:58.744219+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('f2bf4809-2822-4892-9adf-e083b3a1ac99', 'cosmetic', 'easy', 'Dry winter skin', NULL, NULL, ARRAY[]::text[], '{"age":32,"name":"Hina","concern":"flaky, tight skin since winter","skin_type":"dry","current_products":"basic body wash"}'::jsonb, '{"warnings":["Avoid harsh scrubs","Use lukewarm not hot water"],"advice_options":["Apply on damp skin within 3 minutes of bathing for best occlusion","Apply on dry skin once a week","Skip moisturizer to let skin breathe"],"correct_advice":"Apply on damp skin within 3 minutes of bathing for best occlusion","correct_product":"Cream-based moisturizer with ceramides + glycerin","product_options":["Cream-based moisturizer with ceramides + glycerin","Alcohol-based toner","Foaming face wash twice daily"]}'::jsonb, 'Ceramides restore barrier; glycerin is a humectant.', 'The 3-minute rule: occlusive moisturizer right after bathing locks in hydration.', '2026-06-13T08:51:30.090563+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('992912ae-7a23-4d84-aa16-573b4ffb0433', 'cosmetic', 'easy', 'Sunscreen first-time user', NULL, NULL, ARRAY[]::text[], '{"age":24,"name":"Adeel","concern":"daily sun protection","skin_type":"normal","current_products":"none"}'::jsonb, '{"warnings":["UVA penetrates clouds","Re-apply after swimming"],"advice_options":["Apply 2 finger-lengths to face/neck 15 min before sun; reapply q2h outdoors","Apply once a week","Only use when sky is clear"],"correct_advice":"Apply 2 finger-lengths to face/neck 15 min before sun; reapply q2h outdoors","correct_product":"Broad-spectrum SPF 30+ mineral or chemical sunscreen","product_options":["Broad-spectrum SPF 30+ mineral or chemical sunscreen","Only-when-beach sunscreen SPF 8","Tanning oil"]}'::jsonb, 'Broad-spectrum (UVA+UVB) is essential to prevent photoaging and skin cancer.', 'SPF 30 blocks ~97% UVB; higher SPFs offer marginal extra protection but slower reapplication awareness.', '2026-06-13T08:51:30.090563+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('58213242-7cab-46d6-9bbf-a3328323101c', 'cosmetic', 'easy', 'Dandruff', NULL, NULL, ARRAY[]::text[], '{"age":27,"name":"Saad","concern":"flaky scalp","skin_type":"oily scalp","current_products":"regular shampoo"}'::jsonb, '{"warnings":["Persistent dandruff with scalp lesions — refer"],"advice_options":["Leave on scalp for 3-5 minutes before rinsing; alternate with mild shampoo","Rinse off immediately","Use undiluted on dry hair"],"correct_advice":"Leave on scalp for 3-5 minutes before rinsing; alternate with mild shampoo","correct_product":"Ketoconazole 2% shampoo twice weekly","product_options":["Ketoconazole 2% shampoo twice weekly","Daily clarifying shampoo","Avoid washing hair"]}'::jsonb, 'Antifungal shampoo targets Malassezia overgrowth, the cause of seborrhoeic dandruff.', 'Contact time matters more than frequency for medicated shampoos.', '2026-06-13T08:51:30.090563+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('8a458ed0-c1f9-4e1c-9a41-dbf08f4d66a1', 'cosmetic', 'medium', 'Acne in pregnancy', NULL, NULL, ARRAY[]::text[], '{"age":28,"name":"Maria","concern":"mild inflammatory acne","pregnant":true,"skin_type":"combination","current_products":"none"}'::jsonb, '{"warnings":["Avoid all retinoids in pregnancy","Avoid oral tetracyclines"],"advice_options":["Apply pea-sized amount BD on clean skin; avoid eyes; tolerated in pregnancy","Apply tretinoin nightly","Take oral isotretinoin"],"correct_advice":"Apply pea-sized amount BD on clean skin; avoid eyes; tolerated in pregnancy","correct_product":"Azelaic acid 15-20% topical","product_options":["Azelaic acid 15-20% topical","Tretinoin 0.05% cream","Oral doxycycline"]}'::jsonb, 'Retinoids and tetracyclines are teratogenic — azelaic acid is the safest topical option.', 'FDA pregnancy categories: tretinoin (C/D), doxycycline (D); azelaic acid is pregnancy-friendly.', '2026-06-13T08:51:30.090563+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('f9d1ce63-962a-4f3f-8ec7-6ff3a62111e6', 'cosmetic', 'medium', 'Hyperpigmentation', NULL, NULL, ARRAY[]::text[], '{"age":35,"name":"Zara","concern":"melasma on cheeks","skin_type":"sensitive","current_products":"random brighteners"}'::jsonb, '{"warnings":["Strict daily SPF","Avoid sun exposure 10am-4pm"],"advice_options":["Sunscreen is non-negotiable — UV undoes all brightening efforts","Skip SPF on cloudy days","Use lemon juice instead"],"correct_advice":"Sunscreen is non-negotiable — UV undoes all brightening efforts","correct_product":"Vitamin C serum AM + SPF 50 + niacinamide","product_options":["Vitamin C serum AM + SPF 50 + niacinamide","Daily strong glycolic peel","Hydroquinone 4% twice daily without sunscreen"]}'::jsonb, 'Photoprotection is the cornerstone — pigmentation actives without SPF are futile.', 'Hydroquinone, tretinoin, and azelaic acid are evidence-based; combine with daily broad-spectrum SPF.', '2026-06-13T08:51:30.090563+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('0f1a2f03-abe9-4e80-a392-cb1438cd2df7', 'cosmetic', 'hard', 'Retinol + BPO overlap irritation', NULL, NULL, ARRAY[]::text[], '{"age":29,"name":"Rabia","concern":"redness, peeling after starting new routine","skin_type":"sensitive","current_products":"Tretinoin nightly + Benzoyl peroxide AM + glycolic toner"}'::jsonb, '{"warnings":["Retinol degrades when applied with BPO","Avoid layering acids with retinoids"],"advice_options":["Discontinue all actives for 5-7 days; reintroduce one at a time, alternating nights","Combine all actives twice daily","Add salicylic acid on top"],"correct_advice":"Discontinue all actives for 5-7 days; reintroduce one at a time, alternating nights","correct_product":"Pause actives, restore barrier with ceramide moisturizer","product_options":["Pause actives, restore barrier with ceramide moisturizer","Add stronger retinoid","Switch to oral isotretinoin"]}'::jsonb, 'Active stacking causes barrier disruption; recovery requires simplification.', 'Teach ''less is more'' — efficacy plateaus quickly when irritation outpaces benefit.', '2026-06-13T08:51:30.090563+00:00', NULL, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires