te":true},{"item":"Paracetamol IV","actual":300,"expected":300,"investigate":false}]}'::jsonb, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('43cb5018-8edc-4163-9ee5-e73c7a62b20c', 'industry', 'hard', 'Omeprazole 20mg Enteric Capsule', NULL, NULL, ARRAY[]::text[], NULL, '{"release":true}'::jsonb, 'Acid-labile API needs HPMC subcoat between API and enteric coat to prevent degradation.', 'Omeprazole degrades on contact with even trace acid — multi-layer pellet system is mandatory.', '2026-06-13T08:53:08.880861+00:00', '{"qc":[{"test":"Acid resistance 2h","result":"<10% release","shouldPass":true},{"test":"Buffer dissolution 45min","result":"Q=80%","shouldPass":true},{"test":"Assay","result":"98.5%","shouldPass":true}],"env":{"tempRange":[18,22],"humidityRange":[15,30]},"process":{"drying":{"max":45,"min":35,"unit":"°C","target":40},"mixing":{"prompt":"Subcoat application","correct":1,"options":["Apply enteric directly","Apply HPMC subcoat first","No subcoat"]},"coating":{"prompt":"Outer coat","correct":1,"options":["Sugar","Methacrylic enteric","None"]},"packaging":{"prompt":"Packaging","correct":1,"options":["PVC blister","Alu-Alu with desiccant","Open jar"]},"compression":{"prompt":"Capsule fill","correct":1,"options":["Compress into tablets","Fill into HPMC capsules","Direct dispensing"]},"granulation":{"prompt":"Pellet build","correct":1,"options":["Wet granulation","Layering on sugar spheres","Direct compression"]}},"product":"Omeprazole 20mg DR Capsule","release":true,"batchSize":"60,000 capsules","distractors":["Sodium Bicarbonate","Croscarmellose","Talc"],"ingredients":[{"max":20.2,"min":19.8,"name":"Omeprazole","role":"Active","unit":"g","target":20},{"max":305,"min":295,"name":"Sugar Spheres (cores)","role":"Substrate","unit":"g","target":300},{"max":41,"min":39,"name":"HPMC (subcoat)","role":"Subcoat polymer","unit":"g","target":40},{"max":82,"min":78,"name":"Methacrylic Acid Copolymer","role":"Enteric coat","unit":"g","target":80}]}'::jsonb, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
INSERT INTO public.cases (id, mode, difficulty, title, prescription_image_url, electronic_prescription_json, drugs_required, patient_info_json, correct_answer_json, explanation, mentor_tip, created_at, formula_json, shipment_json, requires_compounding, compound_type, compound_data) VALUES ('da445301-28cf-4f2f-bc64-5320153e416e', 'industry', 'hard', 'Combination tablet - incompatible excipient', NULL, NULL, ARRAY[]::text[], NULL, '{"release":true}'::jsonb, 'Avoid sodium bicarbonate distractor — would cause acid-base reaction with caffeine citrate matrix.', 'Always check pre-formulation compatibility studies before approving any new excipient combination.', '2026-06-13T08:53:08.880861+00:00', '{"qc":[{"test":"Weight","result":"672 mg ±1%","shouldPass":true},{"test":"Hardness","result":"9 kp","shouldPass":true},{"test":"Dissolution paracetamol","result":"Q=80% 30min","shouldPass":true},{"test":"Caffeine assay","result":"99%","shouldPass":true}],"env":{"tempRange":[18,25],"humidityRange":[25,45]},"process":{"drying":{"max":55,"min":45,"unit":"°C","target":50},"mixing":{"prompt":"Mixing","correct":0,"options":["10 min @ 20 rpm","30 min @ 40 rpm","60 min @ 80 rpm"]},"coating":{"prompt":"Coating","correct":1,"options":["None","Film","Enteric"]},"packaging":{"prompt":"Packaging","correct":0,"options":["PVC blister","Alu-Alu blister","Open container"]},"compression":{"prompt":"Hardness","correct":1,"options":["4-6 kp","7-11 kp","18-22 kp"]},"granulation":{"prompt":"Granulation","correct":1,"options":["Direct compression","Wet granulation","Dry granulation"]}},"product":"Paracetamol + Caffeine 500/65mg","release":true,"batchSize":"25,000 tablets","distractors":["Lactose Monohydrate","Aspartame","Sodium Bicarbonate"],"ingredients":[{"max":505,"min":495,"name":"Paracetamol","role":"Active","unit":"g","target":500},{"max":66,"min":64,"name":"Caffeine Anhydrous","role":"Active","unit":"g","target":65},{"max":102,"min":98,"name":"Microcrystalline Cellulose","role":"Filler","unit":"g","target":100},{"max":3.2,"min":2.8,"name":"Magnesium Stearate","role":"Lubricant","unit":"g","target":3}]}'::jsonb, NULL, false, NULL, NULL) ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, difficulty = EXCLUDED.difficulty, title = EXCLUDED.title, prescription_image_url = EXCLUDED.prescription_image_url, electronic_prescription_json = EXCLUDED.electronic_prescription_json, drugs_required = EXCLUDED.drugs_required, patient_info_json = EXCLUDED.patient_info_json, correct_answer_json = EXCLUDED.correct_answer_json, explanation = EXCLUDED.explanation, mentor_tip = EXCLUDED.mentor_tip, created_at = EXCLUDED.created_at, formula_json = EXCLUDED.formula_json, shipment_json = EXCLUDED.shipment_json, requires_compounding = EXCLUDED.requires_compounding, compound_type = EXCLUDED.compound_type, compound_data = EXCLUDED.compound_data;
